// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Amerikan, Latin Amerika ve Alman edebiyatı (zor).
const ozLiterature11Zor = <(String, String, List<String>, String)>[
  ('Poe\'nun \'Kompozisyon Felsefesi\' adlı denemesinde ileri sürdüğü \'tek etki birliği\' ilkesi ne söyler?', 'Eserin her ögesinin tek bir duygusal etkiye hizmet etmesi gerektiğini', ['Kısa öykünün her zaman mutlu sonla bitmesi ve ahlaki bir ders vermesi gerektiğini', 'Şiirin yalnız kafiyeli olabileceğini', 'Romanın en az üç bin sözcük içermesi gerektiğini'], 'Poe\'ya göre kısa bir eser tek oturuşta okunmalı ve her ayrıntı önceden belirlenmiş tek bir etkiyi güçlendirmelidir. Bu görüş modern kısa öykü kuramının temelidir.'),
  ('Poe\'nun \'Çalınan Mektup\' öyküsünde kayıp mektubun nerede bulunduğu anlayışı, dedektifin hangi yeteneğini gösterir?', 'Gizlenen şeyin en açıkta durabileceğini kavrayan sezgi ve psikolojik çözümleme', ['Parmak izi tespiti', 'Dedektifin evi parça parça arayıp bütün mobilyaları ve duvarları sökerek mektubu bulması', 'Gizli ajan ağı kurma'], 'Dupin, bakanın mektubu gizlemek yerine sıradan bir mektupmuş gibi herkesin görebileceği yerde bıraktığını fark eder.'),
  ('Hawthorne soyadına neden bir \'w\' harfi eklemiştir?', 'Salem cadı davalarında yargıç olan atasından uzaklaşmak için', ['Fransız kökenini belli etmek için', 'Aile mirasını gizlemek için', 'Yayıncısının isteği üzerine'], 'Hawthorne\'un büyük dedesi John Hathorne, 1692 Salem cadı mahkemesinde yargıçtı. Yazar, soyadını değiştirerek atasının mirasından uzaklaşmak istedi.'),
  ('Hawthorne\'un \'Yedi Çatılı Ev\' romanındaki ailenin kuşaklar boyunca taşıdığı \'lanet\'in kökeni nedir?', 'Atanın bir adamı büyücülükle suçlayıp toprağına el koyması', ['Aile atasının bir yerli kabileye karşı işlediği katliamın ardından gelen kargaşa', 'Yerli halka karşı işlenen bir katliam', 'Bir kilisenin yakılması'], 'Colonel Pyncheon\'un haksızlığı yüzünden Maule ailesinin lanetini taşıdığı inancı, romanın mirasla gelen suç temasını oluşturur.'),
  ('Margaret Fuller\'in Transandantalist çevredeki yeri nedir?', 'Dial dergisinin ilk editörü ve kadın hakları savunucusu olması', ['Walden Gölü\'ndeki ilk yerleşimci olması', 'Brook Farm komününün kurucusu olması', 'Emerson\'ın Boston\'daki yayınevinin kurucusu ve Walden\'in ilk editörü olması'], 'Fuller, \'Dial\' dergisini yönetti ve \'Ondokuzuncu Yüzyılda Kadın\' kitabıyla kadın haklarının erken savunucularından oldu.'),
  ('Charlotte Perkins Gilman\'ın \'Sarı Duvar Kâğıdı\' öyküsünde anlatıcının sarı duvar kâğıdına takıntısı neyin simgesidir?', 'Kadının evlilik ve tıbbi tedavi yoluyla kapatılması ve aklını yitirmesi', ['Eski evin tarihî değerinin ve restorasyon gerekliliğinin sürekli hatırlatılması', 'Çocukluk anılarının canlanışı', 'Evin modasının eskimişliği'], 'Dinlenme tedavisiyle bir odaya kapatılan anlatıcı, duvar kâğıdının ardında hapsolmuş bir kadın görür; öykü, kadın bastırılmasına karşı güçlü bir eleştiridir.'),
  ('Henry James\'in \'Vidanın Çevrilişi\' (Turn of the Screw) adlı uzun öyküsünü tartışmalı kılan nedir?', 'Hayaletlerin gerçek mi yoksa mürebbiyenin hayal ürünü mü olduğunun belirsiz kalması', ['Katilin kimliğinin son sayfada kesin ve tartışmasız biçimde açıklanması ve cezalandırılması', 'Öykünün şiirle yazılmış olması', 'Çocukların hiç konuşmaması'], 'Güvenilmez anlatıcı durumundaki mürebbiyenin gördüklerinin gerçekliği tartışmalıdır; eser bu belirsizliği yüzünden onlarca yorum doğurmuştur.'),
  ('Hemingway\'in \'Güneş de Doğar\' romanında Jake Barnes\'ın savaş yarası, anlatıdaki aşk ilişkisine nasıl yansır?', 'Cinsel yetersizliği yüzünden Brett Ashley\'yle ilişkisi çözümsüz kalır', ['Brett onu kıskançlıkla öldürür', 'Jake\'in ani servet kazanması yüzünden Brett\'in onu terk etmesiyle ilişki biter', 'Brett\'in ailesi evliliği reddeder'], 'Savaş yarası Jake\'i Brett\'e kavuşmaktan alıkoyar; bu, kayıp kuşağın duygusal boşluğunun simgesi olur.'),
  ('Steinbeck\'in \'Gazap Üzümleri\'nin sonunda Rose of Sharon\'un yaptığı davranış neyi simgeler?', 'Açlıktan ölmek üzere olan yabancıyı kendi sütüyle beslemesi, dayanışma ve umudu', ['Çiftlikten kaçışı', 'Çocuğunu terk etmesi', 'Hapse girişi'], 'Bebeğini kaybeden Rose of Sharon, aç bir adama süt verir; bu son sahne, yoksulluk içindeki insan dayanışmasının simgesidir.'),
  ('Miller\'ın \'Köprüden Görünüş\' oyununda liman işçisi Eddie Carbone\'un yıkımına yol açan duygu hangisidir?', 'Yeğenine duyduğu yasak ve yönetilemeyen sevgi ile kıskançlık', ['Zenginlik hırsı yüzünden bir iş arkadaşını sahte belgelerle ihbar etme', 'Siyasi hırs', 'Yabancı düşmanlığı'], 'Eddie, yeğeni Catherine\'in evlenmek istediği adama karşı çıkar ve topluluğun onur yasasını çiğneyerek onu ihbar eder.'),
  ('O\'Neill\'in \'Elektra\'ya Yas Yaraşır\' oyunu hangi antik anlatıyı yeniden işler?', 'Aiskhylos\'un Oresteia üçlemesini', ['Sofokles\'in Kral Oidipus ve Antigone oyunlarını', 'Euripides\'in Medea\'sını', 'Homeros\'un Odysseia\'sını'], 'O\'Neill, Oresteia\'nın olay örgüsünü Amerikan İç Savaşı sonrası bir New England ailesine uyarlamıştır.'),
  ('David Mamet\'nin \'Glengarry Glen Ross\' oyunu hangi ortamı eleştirir?', 'Emlak satıcılarının acımasız rekabetini ve ahlaksızlığını', ['Hastane yönetimini ve doktorlar arasındaki görev dağılımının adaletsizliğini', 'Üniversite sınavlarını', 'Orduyu'], 'Mamet, satış baskısı altındaki ofis çalışanlarının hırsı, hilesi ve ahlaki çöküşünü sert bir konuşma diliyle anlatır.'),
  ('Bir tiyatro eleştirmeni, \'Amerikan Rüyası\'nın çöküşünü bir aile içinde görünür kılan\' iki oyunu karşılaştırıyor. Hangi ikili bu tanıma en iyi uyar?', 'Miller\'ın \'Bir Satıcının Ölümü\' ile O\'Neill\'in \'Gün Batarken Uzun Yolculuk\' oyunu', ['Wilder\'ın \'Bizim Kasaba\' oyunu ile Hansberry\'nin \'Güneşte Bir Kuru Üzüm\' oyunu birlikte', 'Albee\'nin oyunu ile Mamet\'nin oyunu', 'Williams\'ın \'Arzu Tramvayı\' ile Wilder\'ın oyunu'], 'Her iki oyun da bir ailenin yanılsamalarını, başarısızlıklarını ve içsel yıkımını merkeze alır.'),
  ('Carl Sandburg\'ün \'Chicago\' şiirinde kente verdiği benzetme hangisidir?', 'Domuz kasabı ve dünyanın yük taşıyıcısı olan iri omuzlu şehir', ['Işıldayan bir mücevher gibi parlayan, zarif ve ince bir sanat kenti', 'Dingin bir köy', 'Sessiz bir manastır'], 'Sandburg\'ün şiiri, sanayi kentinin kaba gücünü ve işçi enerjisini serbest ölçüyle över.'),
  ('Robert Frost\'un \'Kar Yağarken Bir Akşam Ormanın Kıyısında\' şiirinin kapanışındaki \'Uyumadan önce gidilecek millerim var\' dizesi nasıl yorumlanır?', 'Yaşamın yükümlülüklerinin ve ölüm düşüncesinin çekiciliğine karşı sorumluluk bilinci', ['Atının hasta olması', 'Gece yolculuğunun tehlikesi', 'Kar fırtınasının şiddeti'], 'Tekrarlanan dizeler, kahramanın ormanın dinginliğinden ayrılıp yükümlülüklerine dönmesini ve olası ölüm çağrısını simgeler.'),
  ('Ken Kesey\'nin \'Guguk Kuşu\' romanını hastane koğuşunun içinden anlatan Kızılderili \'Şef Bromden\'in bakış açısı neden önemlidir?', 'Dilsiz görünerek her şeyi gözlemlemesi, olaylara sıra dışı bir bakış kazandırır', ['Hemşirenin zihnine girmesi ve hastane kayıtlarının doğruluğunu gerçekçi biçimde ortaya koyması', 'Olayların tarihlendirilmesine yardım eder', 'Hasta kayıtlarını doğrular'], 'Bromden sağır-dilsiz rolü yaparak herkesi dinler; duyguları ve halüsinasyonları, hastane düzenini bir makine olarak görmesine yol açar.'),
  ('John Updike\'ın \'Tavşan Koş\' romanındaki Harry \'Tavşan\' Angstrom\'un tutumu nasıl özetlenir?', 'Orta sınıf yaşamdan kaçmaya çalışan eski basketbolcunun doyumsuzluğu', ['Savaşta kazandığı madalyalara tutunması ve geçmişteki zaferlerini yüceltmesi', 'Din adamı olma çabası', 'Gazetecilikteki yükselişi'], 'Angstrom, evlilik ve iş sorumluluklarından kaçıp yeniden gençliğinin parlak günlerini arar; roman 1950\'ler Amerika\'sında banliyö yaşamını eleştirir.'),
  ('Philip Roth\'un \'Portnoy\'un Şikâyeti\' romanı hangi biçimde kurgulanmıştır?', 'Bir psikanalistin karşısında yapılan uzun bir itiraf konuşması', ['Mektup romanı', 'Tarihî kronik', 'Gazete haberleri toplamı'], 'Alexander Portnoy, Yahudi aile baskısı ve cinsellik üzerine uzun bir monolog yapar; kitap açık sözlülüğü yüzünden büyük tartışma yarattı.'),
  ('William S. Burroughs\'un \'Çıplak Şölen\' romanı hangi nedenle tartışma yaratmıştır?', 'Uyuşturucu bağımlılığı ve cinselliği doğrusal olmayan, şok edici bir biçimde işlemesi', ['Çocuk edebiyatına aykırı oluşu', 'Din adamlarını övmesi', 'Savaş propagandası yapması'], 'Roman Amerika\'da müstehcenlik davalarına konu oldu; parçalı yapısı ve kesme tekniğiyle Beat edebiyatının en radikal yapıtlarındandır.'),
  ('James Baldwin\'in \'Git Dağlara Söyle\' romanındaki ana tema nedir?', 'Harlem\'de bir kilise çevresinde din, ırk ve kuşak çatışması', ['Avrupa\'da sürgün yaşayan bir ressamın yalnızlığı ve sanat arayışı', 'Tarım işçiliği', 'Savaş gazilerinin dönüşü'], 'Baldwin, kendi çocukluğundan izler taşıyan romanda baba-oğul gerilimini, ırkçılığı ve Hristiyanlığın etkisini ele alır.'),
  ('Ralph Ellison\'ın romanının başında anlatıcının yaşadığı \'yeraltı\' yeri, Dostoyevski\'nin hangi eseriyle bağ kurduran bir imgedir?', 'Yeraltından Notlar', ['Suç ve Ceza', 'Karamazov Kardeşler', 'Budala'], 'Ellison\'ın görünmez adamı bir yeraltı odasında ışıklarla yaşar; bu, Dostoyevski\'nin yalıtılmış bilincini çağrıştıran modern bir yeniden yorumdur.'),
  ('W. E. B. Du Bois\'nın \'Siyah Halkın Ruhları\' kitabında ortaya koyduğu \'çifte bilinç\' kavramı neyi anlatır?', 'Siyah bireyin kendini hem kendi hem beyaz toplumun gözüyle görmesi', ['İki dil bilmenin ve iki kültür arasında kalmanın getirdiği dilsel zorluk', 'İki mesleği birlikte yürütmeyi', 'İkili parti sisteminin etkisini'], 'Du Bois, bu kavramla ırkçı toplumda siyah bireyin parçalanmış kimlik deneyimini tarif etti; kitap 1903\'te yayımlandı.'),
  ('Ursula K. Le Guin\'in \'Omelas\'tan Ayrılanlar\' öyküsü hangi ahlaki ikilemi sorgular?', 'Bir toplumun mutluluğunun tek bir çocuğun acısına dayanması', ['Savaşta masum insanların ölümüne seyirci kalmanın ahlaki yükü ve vicdan azabı', 'Doğanın tahribi', 'Teknolojinin işsizlik yaratması'], 'Kentin refahı bir çocuğun tecritte çektiği acıya bağlıdır; bazı yurttaşlar bunu öğrenince şehirden ayrılır.'),
  ('Louise Glück\'ün 2020\'de aldığı Nobel Edebiyat Ödülü\'nün Amerikan şiiri açısından önemi nedir?', 'Ödülün Amerikalı bir kadın şaire gitmesi', ['Ödülün ilk kez bir şaire, yani şiir türüne verilmesi', 'İlk kez bir ABD\'li yazara verilmesi', 'İlk kez Yidişçe yazan birine verilmesi'], 'Glück\'ün kişisel ve mitolojik çağrışımlı yalın şiiri uluslararası bir takdir kazandı; Nobel şairlere daha önce de verilmişti.'),
  ('Susan Sontag\'ın \'Yorumlamaya Karşı\' denemesindeki temel savı nedir?', 'Sanat yapıtlarının yorumlanmaktan çok duyumsanarak deneyimlenmesi gerektiği', ['Edebiyatın siyasete tabi olması gerektiği', 'Romanların kısa tutulması gerektiği', 'Şiirin ölçülü yazılması gerektiği'], 'Sontag, aşırı yorum çabasının sanatın duyusal gücünü gölgelediğini ve \'bir erotik sanat\'a ihtiyaç olduğunu savundu.'),
  ('Thomas Pynchon\'un \'Lot 49\'un Çığlığı\' romanının kahramanı Oedipa Maas\'ın aradığı şey nedir?', 'Gizli bir posta sisteminin izini sürerken belirsizleşen bir komplo', ['Kayıp bir miras', 'Bir cinayetin faili', 'Bir ülkenin haritası'], 'Oedipa\'nın çözmeye çalıştığı Trystero ağı, anlamın gerçek mi hayal mi olduğunu belirsizleştirir; roman postmodern paranoyanın örneğidir.'),
  ('Don DeLillo\'nun \'Beyaz Gürültü\' romanında Jack Gladney\'nin kuşattığı korku hangisidir?', 'Ölüm korkusu ve tüketim kültürü içinde anlam arayışı', ['Savaşta yaralanma korkusu ve işsizlik kaygısı sonucu gelişen kaygı', 'Sınav kaygısı', 'Yoksulluk korkusu'], 'Roman, tüketim toplumu, medya ve zehirli bulut olayı etrafında ölümden kaçamayan bireyi ironiyle anlatır.'),
  ('Paul Auster\'ın \'New York Üçlemesi\'nde dedektif öyküsü biçimi hangi amaçla kullanılır?', 'Kimlik, dil ve gerçekliğin belirsizliği temalarını işlemek için', ['Gerçek cinayet vakalarını polis soruşturmasıyla aydınlatıp suçluları ifşa etmek için', 'Polis teşkilatını övmek için', 'Çocuk okuru eğlendirmek için'], 'Auster, dedektif kalıbını bozarak çözümsüz kalan vakalar ve kaybolan kimlikler üzerinden varoluşsal sorular sorar.'),
  ('Inca Garcilaso de la Vega\'nın \'Kraliyet Yorumları\' eserinin kendine özgü yanı nedir?', 'İnka dünyasını hem İnka hem İspanyol köklü bir yazarın bakışıyla anlatması', ['İspanyol fatihlerin zaferlerini abartıp yerli halkı küçümsemesi ve kınaması', 'Azteklerin tarihini araştırması', 'Dört dilde şiir yazması'], 'Yazar, İnka soylusu bir anne ile İspanyol bir babanın oğluydu; iki kültüre de ait olduğu için eser, mestizo kimliğin ilk büyük örneklerinden sayılır.'),
  ('José Enrique Rodó\'nun \'Ariel\' adlı denemesinde Latin Amerika gençliğine verdiği öğüt nedir?', 'Maddeci ve yararcı modele karşı ruhsal ve estetik değerleri korumasını', ['Sanayileşmeyi her şeyin önüne koyup sanayi yatırımlarını hızlandırmasını', 'Askerî yönetime geçmesini', 'Avrupa\'dan göçü engellemesini'], 'Uruguaylı Rodó, \'Ariel\'i ruhsal değerlerin, \'Caliban\'ı ise maddeciliğin simgesi olarak kullandı; yapıt Latin Amerika\'da geniş etki yarattı.'),
  ('Rómulo Gallegos\'un \'Doña Bárbara\' romanı hangi karşıtlığı simgeleştirir?', 'Barbar toprak sahibi kadınla uygar avukat Santos Luzardo\'nun çatışması', ['Din ile bilimin çatışmasını, kilise ile üniversite arasındaki gerilimi anlatması', 'Şehir ile liman', 'Çocuk ile yaşlı'], 'Venezuelalı Gallegos, Sarmiento geleneğiyle uygarlık-barbarlık çatışmasını Llanos ovalarındaki toprak mücadelesi üzerinden anlatır.'),
  ('Ciro Alegría\'nın \'Dünyanın Geniş ve Yabancı Olanı\' romanı hangi toplumsal çatışmayı anlatır?', 'Perulu yerli köylülerin toprak ağalarına karşı hak mücadelesini', ['Denizcilerin kaptanlarına karşı çıkardığı isyanı ve gemideki hayatı', 'Madenci sendikalarını', 'Şehir soylularının çöküşünü'], 'Yerlici (indigenista) romanın başyapıtlarından olan eser, And köylülerinin topraklarını yitirişini anlatır.'),
  ('Borges\'in \'Pierre Menard, Don Kişot\'un Yazarı\' öyküsünde kahramanın Cervantes\'in metnini sözcüğü sözcüğüne yeniden yazma çabası neyi gösterir?', 'Aynı metnin farklı çağda farklı anlam kazanmasını göstermek', ['Cervantes\'in kayıp bir bölümünü bularak yayımlamak', 'Don Kişot\'u çağdaş bir romana dönüştürüp güncellemek', 'Cervantes\'in romanını başka bir dile çevirip Avrupa\'ya tanıtmaya çalışmak'], 'Menard\'ın kimseden kopya etmeden aynı satırları yazma tasarısı, anlamın okurun ve çağın bağlamıyla değiştiğini savunur.'),
  ('Borges\'in \'Tlön, Uqbar, Orbis Tertius\' öyküsünde gerçek dünyayı değiştiren şey nedir?', 'Hayalî bir gezegenin ansiklopedisinden doğan düşüncelerin gerçekliği ele geçirmesi', ['Bir uzaylı istilası', 'Kitapların yasaklanması', 'Bir veba salgını'], 'Kurgusal bir ansiklopedi giderek gerçek dünyaya sızar; öykü, bilginin gerçekliği biçimlendirdiğini sorgular.'),
  ('Antonio Skármeta\'nın \'Ateşli Sabır\' romanı ile Neruda arasındaki ilişki nedir?', 'Şair, romanda bir postacıyla dostluk kuran karakterdir', ['Neruda romanın yazarıdır ve onu Paris\'te sürgündeyken kaleme almıştır', 'Neruda romanın çevirmenidir', 'Romanın konusu Neruda\'nın ölümüdür'], 'Roman, Neruda\'nın Isla Negra\'daki postacısının öyküsünü anlatır; sinemaya \'Postacı\' adıyla uyarlanmıştır.'),
  ('César Vallejo\'nun \'Trilce\' kitabı hangi yönüyle avangart bir kırılma yaratmıştır?', 'Dilin yapısını bozan, yeni sözcükler ve sıra dışı sözdizimiyle yazılmış olması', ['Geleneksel sone biçimini sürdürmesi', 'Mitolojik kahramanlara yönelmesi', 'Resmî yazı diline uyması'], 'Perulu Vallejo, \'Trilce\'de dilin sınırlarını zorlayarak duyguyu çözülmüş sözdizimiyle verdi; kitap Latin Amerika şiirinin en özgün yapıtlarından biridir.'),
  ('Vicente Huidobro\'nun öncülük ettiği \'yaratımcılık\' (creacionismo) akımı şiirden ne bekler?', 'Doğayı taklit etmeyip kendi gerçekliğini yaratmasını', ['Doğayı gözleyip olduğu gibi ve eksiksiz betimlemesini', 'Siyasi görüşleri duyurmasını', 'Halk şarkılarını derlemesini'], 'Huidobro, \'Şair küçük bir Tanrı\'dır\' diyerek şiirin yeni bir dünya yaratması gerektiğini savundu; \'Altazor\' bu anlayışın uzun şiiridir.'),
  ('Nicanor Parra\'nın \'antişiir\' (antipoema) anlayışı nasıl tanımlanabilir?', 'Süslü şiir dilini bırakıp günlük konuşmaya, ironiye ve gündelik dile yaslanan şiir', ['Şiiri tamamen müzikle değiştirmek', 'Mitolojiyi merkeze almak', 'Dizeleri sadece resmî dille yazmak'], 'Şilili Parra, romantik ve yüksek perdeden şiire karşı alaycı, açık ve konuşma diline yakın bir şiir çizgisi kurdu.'),
  ('García Márquez\'in 1982\'de Nobel Edebiyat Ödülü\'nü aldığı konuşmasının başlığı olan \'Latin Amerika\'nın Yalnızlığı\' neyi savunur?', 'Kıtanın gerçekliğinin Avrupa ölçütleriyle anlaşılamayacağını', ['Kıtanın Avrupa\'ya katılmasını', 'Kıtanın yok olmasını', 'Yalnızca yazarların özgür olması gerektiğini'], 'Konuşma, Latin Amerika\'nın doğa, şiddet ve tarih bakımından olağanüstü gerçekliğinin Avrupa kalıplarıyla yorumlanamayacağını söyler.'),
  ('Vargas Llosa\'nın \'Teyze Julia ve Palavracı\' romanında iki farklı anlatı hattı nasıl bir arada ilerler?', 'Gençlik aşkını anlatan bölümler ile radyo dizisi bölümleri dönüşümlü gelir', ['Yazarın mektupları ile yargı kayıtları dönüşümlü gelir', 'Gazete haberleri ile kronikler dönüşümlü gelir', 'Rüyalar ile bilimsel makaleler dönüşümlü gelir'], 'Yazarın kendi yaşamından esinlenen bölümler ile radyo oyunlarının bölümleri iç içe geçer; roman yapı bakımından yenilikçidir.'),
  ('José Donoso\'nun \'Gecenin Uğursuz Kuşu\' romanında anlatıcının kimliği nasıl bir özellik gösterir?', 'Kimlik sürekli kayar ve karakterler birbirine karışır', ['Tek ve değişmeyen bir anlatıcıdır', 'Çocuk anlatıcıdır', 'Yazar kendini gösterir'], 'Roman, bir malikânede yaşayan aile ve yaşlı kadınlar arasında gerçekle kâbusun sınırlarını bulanıklaştırır.'),
  ('Cortázar\'ın \'Cronopios ve Famalar\' kitabındaki \'cronopio\' tipinin özelliği nedir?', 'Hayalperest, düzensiz ve şairane bir yaşam tarzı taşıması', ['Aşırı disiplinli bir iş insanı olması', 'Kalabalıkları yönetmesi', 'Politikayla uğraşması'], 'Cronopios, famalar ve esperanzalar adlı kurgusal tipler, insan davranışlarını mizahla sınıflandırır.'),
  ('Brezilya\'da 1922\'deki Modern Sanat Haftası\'nın edebiyat açısından önemi nedir?', 'Avrupa etkisinden bağımsız modernist hareketin başlangıcı', ['Köleliğin kaldırılmasını ilan eden yasa tasarısının Parlamento\'da kabul edilmesi', 'İlk romanın yayımlanması', 'Cumhuriyet\'in ilanı'], 'São Paulo\'da düzenlenen etkinlik, Brezilya modernizminin dönüm noktasıdır; Oswald de Andrade, Mário de Andrade gibi yazarlar bu çevrede yer aldı.'),
  ('Oswald de Andrade\'ın \'Yamyamcı Manifesto\'sundaki ana düşünce nedir?', 'Avrupa kültürünü yutup kendi özgün biçimine dönüştürmek', ['Avrupa\'dan tamamen kopmak', 'Yerli dilleri yasaklamak', 'Eski sömürgeye dönüş'], 'Manifesto, Brezilya\'nın dış etkileri yamyamlar gibi hazmedip kendi kültürüne katması gerektiğini savunan şakacı ve radikal bir metindir.'),
  ('Vargas Llosa\'nın \'Teke Şenliği\' romanında geçmiş ve şimdi nasıl iç içe örülür?', 'Urania\'nın dönüşü ile diktatörün son günleri dönüşümlü anlatılır', ['Trujillo\'nun çocukluğu ve ölümü ters kronolojik sırayla ve tek anlatıcıyla aktarılır', 'Roman yalnızca günlüklerden oluşur', 'Tek bir gün boyunca geçer'], 'Üç anlatı hattı, Urania\'nın yıllar sonra babasıyla yüzleşmesini ve diktatörün suikast gününü birleştirir.'),
  ('Ernesto Sábato\'nun, Arjantin\'de 1983\'ten sonra başkanlık ettiği \'Nunca Más\' komisyonunun görevi neydi?', 'Diktatörlük döneminde kaybolan insanlarla ilgili suçları araştırmak', ['Seçimlerin güvenliğini sağlamak, oy sayımını denetlemek ve sonuçları duyurmak', 'Anayasa taslağı hazırlamak', 'Yeni üniversite kurmak'], 'Sábato, diktatörlük sırasındaki insan hakları ihlallerini ve kayıpları belgeleyen komisyonu yönetti; rapor \'Nunca Más\' adıyla yayımlandı.'),
  ('Adolfo Bioy Casares\'in \'Morel\'in İcadı\' romanındaki ıssız adada kahramanın gördüğü insanların gerçeği nedir?', 'Makineyle kaydedilip sürekli yeniden oynatılan görüntülerdir', ['Gerçek insanlardır ama konuşmayı bırakmış sessiz bir topluluktur', 'Hayalet olmuş ölülerdir', 'Rüya gören yerlilerdir'], 'Morel\'in makinesi insanı ve çevresini görüntü olarak sonsuza dek tekrarlar; roman gerçekliğin sınırlarını sorgulayan fantastik bir aşk anlatısıdır.'),
  ('Vargas Llosa\'ya Nobel Edebiyat Ödülü hangi gerekçeyle verilmiştir?', 'İktidar yapılarını haritalaması ve bireyin direnişini keskin imgelerle anlatması', ['Çocuk edebiyatında yarattığı klasikler ve gençlere yönelik romanlarındaki başarısı', 'Yalnızca şiirdeki yeniliği', 'Tarih araştırmalarındaki titizliği'], 'İsveç Akademisi, 2010\'da onu iktidar yapılarının haritasını çıkarmaktaki ustalığı ve bireysel direnişin canlı betimleri nedeniyle ödüllendirdi.'),
  ('Sebastian Brant\'ın \'Ahmaklar Gemisi\' (Narrenschiff) eseri hangi amaçla yazılmıştır?', 'Çağın budalalıklarını simgesel bir gemi yolculuğuyla hicvetmek', ['Bir deniz savaşını ve gemi komutanlarının zaferlerini ayrıntılı anlatmak', 'Bir gezginin seferini kayda geçirmek', 'Kilisenin kuruluşunu anlatmak'], '1494\'te yayımlanan eser, çeşitli budala tiplerini bir gemide toplayarak ahlaki bir hiciv sunar.'),
  ('Lessing\'in \'Emilia Galotti\' oyununda babanın kızına yönelik davranışı neyi gösterir?', 'Kızını soylu prensin saldırısından kurtarmak için kendi eliyle öldürmesi', ['Kızını yüksek mevkili bir soyluya vermek için ona baskı yapan babanın hırsı', 'Prensin lütfunu kazanma çabasını', 'Kız kardeşinin intikamını alışını'], 'Odoardo, kızı prensin gözdesi olmasın diye onu öldürür; oyun burjuva trajedisinin örneğidir ve soylu zorbalığını eleştirir.'),
  ('Klopstock\'un \'Mesih\' destanı Alman şiirine hangi yeniliği getirmiştir?', 'Hexameter ölçüsüyle Almanca şiire yüksek bir duygusallık katması', ['Halk türkülerini yasaklayıp yalnızca Latince şiir yazılmasını savunması', 'Sadece nesir kullanması', 'Mizahı öne çıkarması'], 'Klopstock, Antik Yunan hexameterini Almancaya uyguladı ve duygu yüklü şiir dilini Sturm und Drang kuşağına açtı.'),
  ('Schiller\'in \'Çan Şarkısı\' şiiri hangi imgeyle insan yaşamını anlatır?', 'Bir çan dökümünün aşamalarıyla doğumdan ölüme yaşamı', ['Bir geminin rotasıyla', 'Bir mevsimin değişimiyle', 'Bir şatonun yapılışıyla'], 'Şiir, çan dökümcülüğü sürecini aile, çalışma ve toplumsal düzen tasarımıyla birlikte işler.'),
  ('Tieck\'in \'Çizmeli Kedi\' oyununu özgün kılan nedir?', 'Seyircinin ve oyun içindeki oyunun sahnede tartışılmasıyla romantik ironinin kullanılması', ['Çok uzun bir destan olması', 'Halk dilinde yazılmamış olması', 'Yalnız çocuklara oynanması'], 'Oyunda seyirciler sahnede karakterlerle konuşur; sahne yanılsaması bilinçli olarak bozulur. Bu, \'romantik ironi\'nin tipik örneğidir.'),
  ('Kleist\'ın \'Kırık Testi\' oyunu hangi türdedir ve ana olay nedir?', 'Komedi; yargıcın kendi suçunu aramak zorunda kalması', ['Trajedi; bir kralın tahtını yitirmesi ve sürgüne gitmesi', 'Epik şiir; savaş', 'Opera; aşk'], 'Yargıç Adam, kırık testi davasında kendi suçlu olduğunu saklamaya çalışırken yargılama komediye dönüşür; oyun Alman komedi geleneğinin şaheseridir.'),
  ('Hölderlin\'in yaşamının son otuz küsur yılı hangi koşulda geçmiştir?', 'Tübingen\'de bir marangozun kulesinde akıl hastası olarak', ['Paris\'te sürgünde', 'Atina\'da gezgin olarak', 'Weimar sarayında bakan olarak'], 'Hölderlin, 1806\'dan sonra Tübingen\'de Ernst Zimmer\'in evindeki \'kule\'de yaşadı; şiirleri ölümünden çok sonra değer buldu.'),
  ('Fouqué\'nin \'Undine\' masalı hangi motife dayanır?', 'Ruhsuz bir su perisinin insanla evlenip ruh kazanması', ['Genç bir şövalyenin ejderhayı öldürüp hazineyi kazanması', 'Kayıp bir hazine', 'Ölümsüzlük iksiri'], 'Undine, insanla evlenince ruh kazanır ama koca ona ihanet edince sulara dönmek zorunda kalır; öykü Romantik su perisi masallarının klasiğidir.'),
  ('Kleist\'ın \'Marquise von O...\' novellasının merkezindeki olay nedir?', 'Kocasız bir kadının hamile kalıp babayı ilanla araması', ['Bir şatodaki hazinenin çalınması ve suçluların aranması', 'Bir düello', 'Bir şatonun yanması'], 'Marquise\'nin bilmediği biçimde hamile kalışı ve baba adayını ilanla araması, toplumsal tepki ve onur sorununu işler.'),
  ('Hofmannsthal\'in \'Chandos Mektubu\' neyi anlatır?', 'Sözcüklerin gerçeği ifade edemediğine dair dil krizini', ['Birinci Dünya Savaşı cephesindeki bir anıyı ve yaşananları', 'Bir aşk hikâyesini', 'Bir ticaret anlaşmasını'], 'Kurgusal Lord Chandos\'un yazdığı mektup, yazarın dile güveninin sarsılışını gösterir ve modernizmin dil sorgulamasını simgeler.'),
  ('Georg Trakl\'in şiirlerinin ortak özelliği nedir?', 'Karanlık, çürüme ve ölüm imgeleriyle yüklü yoğun dil', ['Neşeli doğa betimlemeleri', 'Siyasi öğreticilik', 'Komik hiciv'], 'Trakl, savaş sırasında hayatını kaybeden bir şairdir; dizeleri solgun renkler ve yıkım duygusuyla doludur.'),
  ('Döblin\'in romanında kullandığı \'montaj tekniği\' hangi yazarın etkisini de gösterir?', 'James Joyce ve Dos Passos\'un', ['Dante ve Petrarca\'nın', 'Cervantes ve Quevedo\'nun', 'Gogol ve Çehov\'un'], 'Reklam, haber ve sokak sesleri kurguyla iç içe geçirilir; bu, modern kent romanının önemli bir tekniğidir.'),
  ('Mann\'ın \'Doktor Faustus\' romanında bestecinin Faust efsanesi ile ilişkisi nedir?', 'Dehaya ulaşmak için şeytanla yaptığı anlaşma, Alman kültürünün trajedisini simgeler', ['Bir büyücünün kitabını bulması', 'Bir bilginin Mısır yolculuğu', 'Bir şairin aşk acısı'], 'Adrian Leverkühn\'ün öyküsü, Alman kültürünün Nazizme sürüklenişinin alegorisidir. Roman 1947\'de yayımlandı.'),
  ('Hesse\'nin \'Cam Boncuk Oyunu\' romanındaki Kastalya topluluğu neyi simgeler?', 'Bilgi ve sanatı birleştiren soyut entelektüel dünyayı', ['Savaşçı, disiplinli ve silahlı bir askerî topluluğu simgeler', 'Ticaret loncasını', 'Çiftçi köyünü'], 'Josef Knecht, Kastalya\'nın yüksek düzeyli oyununun ustası olur ama sonunda gerçek yaşamla bağ kurmak için ondan ayrılır.'),
  ('Erwin Piscator\'un Alman sahnesine katkısı nedir?', 'Epik tiyatro tekniklerini, film ve projeksiyonu sahneye getirerek siyasal tiyatroyu geliştirmesi', ['Opera yazarlığı', 'Shakespeare çevirileri', 'Marionette tiyatrosu kurması'], 'Piscator, 1920\'lerde siyasal tiyatroyu teknik yeniliklerle zenginleştirdi; Brecht\'in epik tiyatrosuna zemin hazırladı.'),
  ('Christa Wolf\'un \'Bölünmüş Gökyüzü\' romanında hangi tarihsel gerçeklik işlenir?', 'Almanya\'nın Doğu ve Batı olarak bölünmesi ve bunun aşk ilişkisine etkisi', ['Fransız Devrimi', 'Birinci Dünya Savaşı', 'Rusya\'daki iç savaş'], 'Roman, Doğu Almanya\'dan Batı\'ya kaçan sevgilisi yüzünden ikilemde kalan genç kadını anlatır.'),
  ('Peter Weiss\'ın \'Marat/Sade\' oyunu nasıl bir kurguya sahiptir?', 'Akıl hastanesindeki hastaların Marat\'nın ölümünü sahnelemesi', ['Bir saray entrikasının krala yönelik suikast olarak gelişmesi ve çözülmesi', 'Bir gemi seferi', 'Bir mahkeme duruşması'], 'Oyunun içinde oyun biçimi, Sade\'ın yönettiği hastalar eliyle devrim ve bireysellik tartışmasını yürütür.'),
  ('Peter Handke 2019\'da Nobel Edebiyat Ödülü\'nü aldığında jürinin öne çıkardığı özellik nedir?', 'İnsan deneyiminin kenar noktalarını ve dilsel özgünlüğü araştıran etkili eserleri', ['Politik diplomasisi', 'Tiyatrodaki sansasyon', 'Tarihî romanları'], 'Avusturyalı Handke, \'Kaleci\'nin Penaltı Korkusu\' gibi eserlerle dilin yetersizliğini ve yabancılaşmayı işler; ödül tartışmalara da yol açtı.'),
  ('Süskind\'in \'Kontrbas\' adlı tek kişilik oyunu hangi duruma odaklanır?', 'Orkestradaki bir kontrbasçının sanatla ilişkisini ve yalnızlığını', ['Bir politikacının seçimi', 'Bir komutanın savaşı', 'Bir bilim insanının icadı'], 'Kontrbasçı, orkestra içindeki önemsiz konumunu ve bir sopranoya duyduğu aşkı anlatır; oyun monolog biçimindedir.'),
  ('Uwe Johnson\'ın \'Jahrestage\' romanı hangi iki dünyayı birleştirir?', 'New York\'ta bir günlük yaşam ile Doğu Almanya\'daki geçmiş', ['Moskova ile Berlin', 'Paris ile Roma', 'Viyana ile Zürih'], 'Gesine Cresspahl\'ın bir yıllık günlüğü, hem Amerika\'daki şimdiyi hem de Mecklenburg\'daki geçmişi anlatır.'),
  ('Sherwood Anderson\'ın \'Winesburg, Ohio\' kitabında \'grotesk\' kavramı neyi anlatır?', 'Bastırılmış tutkularla çarpıklaşmış kasaba insanlarını', ['Dev gibi büyük ve görkemli kahramanları destansı biçimde', 'Fantastik canavarları', 'Kraliyet törenlerini'], 'Kitap, bir kasabanın tuhaf ve yalnız insanlarını birbirine bağlı öykülerle anlatır; Faulkner ve Hemingway\'i etkilemiştir.'),
  ('Fitzgerald\'ın \'Gece Hafiftir\' romanında Dick Diver\'ın çöküşü nasıl gerçekleşir?', 'Hasta karısına ve lüks yaşama harcadığı enerji yüzünden çöker', ['Savaşta yaralanmasıyla', 'Suçlu bulunmasıyla', 'Servet kazanmasıyla'], 'Psikiyatrist Dick, zengin hasta karısıyla evliliğinin yıpratıcı etkisiyle ve alkole sığınarak parlak kariyerini yitirir.'),
  ('Dreiser\'in \'Sister Carrie\' romanı o dönemde neden tartışma yaratmıştır?', 'Ahlaki cezalandırma olmadan başarıya ulaşan bir kadını göstermesi', ['Kralı ve devlet yönetimini keskin biçimde eleştirerek yasaklanması', 'Dinî ayinleri alaya alması', 'Savaşı öven bir tutum izlemesi'], 'Carrie\'nin yükselişi ahlaki bir cezayla sonuçlanmaz; yayıncı kitabı sansürle dağıtmaktan kaçındı.'),
  ('Jack London\'ın \'Martin Eden\' romanında kahramanın trajedisi nedir?', 'Başarıya ulaştıktan sonra anlamını yitirmesi ve yok oluşu seçmesi', ['Savaşta ölmesi', 'Hapse girmesi', 'Bir hastalığa yakalanması'], 'Martin, çabasıyla yazar olur ama sınıfsal çevresi ve idealleri çöktüğünde yaşamdan kopar; roman otobiyografik öğeler taşır.'),
  ('Thornton Wilder\'ın \'Aziz Louis Rey Köprüsü\' romanı hangi soruyu araştırır?', 'Köprüde ölen beş kişinin ölümlerinde ilahi plan olup olmadığını', ['Köprünün yapı mühendisliğini ve çökme nedenlerini teknik olarak incelemeyi', 'Köprü bekçisinin ihaneti', 'Bir hazinenin yerini'], 'Rahip Juniper, rastlantısal gibi görünen ölümleri açıklamaya çalışır; roman kader ve rastlantı üzerinedir.'),
  ('Gertrude Stein\'ın \'Bir gül bir gül bir gül bir gül\' dizesindeki tekrar tekniği neyi gösterir?', 'Sözcüklerin anlam ve ritminin tekrarla yeniden duyumsatılmasını', ['Şiirin kuralsızlığını', 'Şairin unutkanlığını', 'Dilin yokluğunu'], 'Stein, tekrar ve kesintisiz anlatımla dili günlük kullanımdan arındırıp yeniden algılatmaya çalışan bir modernizm anlayışı geliştirdi.'),
  ('Shirley Jackson\'ın \'Perili Tepedeki Ev\' romanında doğaüstü olayların ana etkisi nedir?', 'Eleanor\'un ruhsal çöküşünü güçlendirip belirsizleştirmesi', ['Evin satılması', 'Bir hazinenin bulunması', 'Bir cinayetin çözümü'], 'Eleanor, evin etkisi altında gerçekle kuruntuyu ayırt edemez; roman, doğaüstü ile ruhsal çözülmenin iç içeliğini işler.'),
  ('Katherine Anne Porter\'ın \'Aptallar Gemisi\' romanı nasıl bir anlatı sunar?', 'Nazizm öncesi Almanya\'ya giden gemide insanlığın panoraması', ['Hazine peşindeki korsanların gemideki macerası ve deniz savaşları', 'Bir keşif seferi', 'Bir ticaret yolculuğu'], 'Gemideki yolcuların önyargıları ve zayıflıkları, dünya düzeninin çöküşüne alegori olarak okunur.'),
  ('Edith Wharton\'ın \'Ethan Frome\' romanının anlatıcısı olayları nasıl aktarır?', 'Kasabada duyduklarından hareketle çerçeve hikâye kurarak', ['Doğrudan kahramanın günlüğünden ve mektuplarından alıntılarla', 'Mahkeme tutanağından', 'Rüyalardan'], 'Anlatıcı, Ethan\'ı tanıdıktan sonra geçmişini kurgular; sert New England kışı ve kaçınılmaz yazgı bu çerçevede verilir.'),
  ('Neruda\'nın \'Kaptan\'ın Dizeleri\' kitabı ilk kez neden adı belirtilmeden yayımlanmıştır?', 'Şair, Matilde\'yle ilişkisini gizli tutmak istemiştir', ['Yayıncısı kitabın içeriğini beğenmediği için istememiştir', 'Sansür nedeniyle', 'Çok kısa olduğu için'], 'Kitap 1952\'de adı olmadan yayımlandı; Neruda sonradan yazarlığını kabul etti. Dizeler Matilde\'ye duyduğu aşkı anlatır.'),
  ('Gabriela Mistral\'in \'Desolación\' (Yıkım) kitabı hangi nedenle önem taşır?', 'Kendi acısını dile getiren ilk büyük şiir kitabı olması', ['Yalnızca siyasal hicivler ve devlet eleştirileri içermesi', 'Doğa betimlemelerinden oluşması', 'Tamamen çevirilerden oluşması'], 'Mistral, sevgilisinin intiharından sonra yazdığı şiirleri bu kitapta topladı; yapıt onu kıtada tanıttı.'),
  ('Ernesto Cardenal\'in şiirlerinin ayırıcı özelliği nedir?', 'Hristiyanlık ve toplumsal adalet arayışını birleştirmesi', ['Soyut dil oyunları ve anlamsızlığa varan sözcük dizilerinden oluşması', 'Antik mitolojiyi yeniden yazma', 'Müzikle sınırlı şiir'], 'Nikaraguali rahip şair Cardenal, yoksulların yanında duran bir inanç anlayışını şiirine taşıdı.'),
  ('Rosario Castellanos\'un \'Balún Canán\' romanı hangi sorunu işler?', 'Meksika\'da Çiapas\'taki yerli halkın toprak sahipleri karşısındaki durumunu', ['Büyük şehir yoksulluğunu', 'Denizcilik sektörünü', 'Eğitim reformunu'], 'Meksikalı Castellanos, bir toprak sahibi ailenin kız çocuğunun bakışıyla yerli-mestizo ilişkisini ve cinsiyet eşitsizliğini anlatır.'),
  ('Clarice Lispector\'in \'G.H.\'ye Göre Tutku\' romanında merkezi deneyim nedir?', 'Bir hamam böceğini ezmesi sonucunda yaşadığı iç dönüşüm', ['Bir tabloyu satması', 'Bir yolculuk planı', 'Bir sınav sonucu'], 'G.H., hizmetçisinin odasında gördüğü hamam böceğiyle yüzleşirken benliğini ve gerçekliğini sorgular.'),
  ('Hartmann von Aue\'nun \'Zavallı Heinrich\' öyküsü neyi anlatır?', 'Cüzzama yakalanan şövalyenin bir kızın fedakârlığıyla iyileşmesini', ['Bir ejderha avını', 'Bir kralın tahta çıkışını', 'Bir haçlı seferini'], 'Heinrich\'in iyileşmesi için bir kızın kendini kurban etmeye hazır olması, sonunda tanrısal merhametle ödüllendirilir.'),
  ('Martin Opitz\'in 1624 tarihli \'Alman Şiir Kitabı\' ne işe yaramıştır?', 'Almanca şiir için ölçü ve kafiye kuralları koymuştur', ['Latince şiir yazmayı öğretmek için hazırlanmış bir ders kitabıdır', 'Halk türkülerini derlemiştir', 'Tiyatro oyunları yayımlamıştır'], 'Opitz, Almanca şiirin hece vurgusuna dayalı ölçü kurallarını koydu ve Barok şiirin temel kılavuzu oldu.'),
  ('Lichtenberg\'in aforizmalarının özelliği nedir?', 'Kısa ve zekice gözlemlerle toplumu ve insanı eleştirmesi', ['Uzun destan anlatımı', 'Dinî vaazlar', 'Tarihî anlatılar'], 'Aydınlanma dönemi fizikçisi ve yazarı Lichtenberg, aforizmaları \'Karalama Defterleri\'nde topladı; Schopenhauer ve Nietzsche\'yi etkiledi.'),
  ('Goethe ile Schiller\'in \'Xenien\' adlı ortak çalışmasının niteliği nedir?', 'Çağın ikinci sınıf yazarlarını hicveden kısa dörtlükler', ['Bir kasabanın tarihini anlatan büyük bir roman serisi ve ciltleri', 'Bir tiyatro oyunu', 'Bir ansiklopedi'], '1796\'da yayımlanan epigramlar, edebi çevreyi eleştirdi ve Weimar klasisizminin kendini savunma biçimiydi.'),
  ('Lenz\'in \'Öğretmen\' (Der Hofmeister) oyunu hangi toplumsal sorunu eleştirir?', 'Soylu ailelerde çalışan öğretmenlerin aşağılanmasını', ['Askerlik hizmetinin köylü gençler üzerindeki ağır baskısını', 'Köylü vergilerini', 'Din okulu sistemini'], 'Sturm und Drang dönemine ait oyun, burjuva kökenli öğretmenin sınıfsal baskıya ve boyun eğdirilişine dikkat çeker.'),
  ('Gottfried August Bürger\'in \'Lenore\' baladı hangi temayı işler?', 'Savaştan dönmeyen sevgilinin hayaletinin sevgilisini alıp götürmesini', ['Bir denizci masalını', 'Bir kralın düğününü', 'Bir hazine avını'], 'Balad, ölü sevgilinin gece hayaletiyle gelip kızı mezara götürmesini anlatan korku şiiridir; Sturm und Drang\'ın balad geleneğine örnektir.'),
  ('Hem anlatıcının sınırlı bilgisi hem de belirsiz sonla okuru yorum yapmaya iten bir eser aranıyor. Hangisi uygun olur?', 'James\'in \'Vidanın Çevrilişi\' uzun öyküsü', ['Defoe\'nun \'Robinson Crusoe\' adlı macera romanı', 'Bunyan\'ın \'Hacı\'nın İlerleyişi\'', 'Twain\'in \'Tom Sawyer\'ı'], 'Mürebbiyenin güvenilmez anlatımı hayaletlerin gerçekliğini belirsiz bırakır; bu özellik Henry James\'in öyküsünü yoruma açık kılar.'),
  ('Kafka\'nın \'Dava\'sı ile Dürrenmatt\'ın \'Fizikçiler\'i arasındaki ortak tema hangisidir?', 'Bireyin kendi kontrolü dışındaki sistemler karşısındaki çaresizliği', ['Doğa sevgisi', 'Köylü ayaklanması', 'Aşkın zaferi'], 'Josef K. anlaşılmaz bir yargı mekanizması, fizikçiler ise bilimin kontrolsüz sonuçları karşısında çaresizdir.'),
  ('García Márquez\'in \'Yüzyıllık Yalnızlık\'ı ile Grass\'ın \'Teneke Trampet\'i arasındaki anlatım benzerliği nedir?', 'Tarihi abartılı ve olağanüstü öğelerle anlatmaları', ['İkisinin de baştan sona uzun şiir olarak yazılmış olması', 'İkisinin de çocuk romanı olması', 'İkisinin de mektuplardan oluşması'], 'Her iki roman, ulusun tarihini fantastik ve grotesk öğelerle yeniden anlatır; okur gerçekle abartı arasında dolaşır.'),
  ('Whitman\'ın serbest dizesi ile Neruda\'nın \'Canto General\'indeki dizeler arasındaki ilişki nasıl açıklanır?', 'İkisi de geniş soluklu sesle halkı ve toprağı şiirleştirir', ['İkisi de katı kafiye düzenine uyan, kısa ve ölçülü sonelerdir', 'İkisi de klasik Yunan ölçüsüyle yazılmıştır', 'İkisi de tiyatro metnidir'], 'Neruda, Whitman\'ın demokratik şiirinden etkilenerek kıtanın doğasını ve halkını epik bir serbest şiirle anlattı.'),
  ('Borges ve Kafka\'nın ortak yönü olarak hangisi gösterilebilir?', 'Kısa anlatılarla kapalı, felsefi ve gerçeküstü dünyalar kurmaları', ['Uzun aşk romanları ve melodramlar yazarak geniş okur kitlesine ulaşmaları', 'Halk türküsü derlemeleri', 'Gazete yazarlığı yapmaları'], 'Borges, Kafka\'yı kendine öncü olarak sayıyordu; ikisi de kısa metinlerde metafizik ve belirsiz dünyalar kurar.'),
  ('Walt Whitman\'ın demokrasi anlayışıyla Thoreau\'nun bireyciliği arasındaki fark nedir?', 'Whitman kitleyle özdeşleşip onu över; Thoreau devletten çekilip bireysel vicdana dayanır', ['Whitman devleti reddeder; Thoreau kitleyi över', 'İkisi de krallığı savunur', 'İkisi de endüstriyi över'], 'Whitman halkı kucaklayan geniş bir \'ben\' tasarlar; Thoreau ise vicdani ret ve yalın yaşamda bireysel özerkliği vurgular.'),
  ('Latin Amerika\'da Boom ve Alman \'Gruppe 47\' kuşağı arasındaki ortak özellik nedir?', 'İkisi de edebiyatı toplumsal belleği yeniden kurmak için kullanan yazar toplulukları üretmiştir', ['İkisi de aynı yayınevine bağlı kalmıştır', 'İkisi de tiyatro yasağı altında yazmıştır', 'İkisi de monarşiyi desteklemiştir'], 'Boom, kıtanın kimliğini; Gruppe 47 savaş sonrası Almanya\'sının bellek ve suçluluğunu sorguladı.'),
  ('Cortázar\'ın \'Seksek\'i ile Fuentes\'in \'Terra Nostra\'sı hangi yönüyle ortaktır?', 'Deneysel yapı ve geleneksel romanı bozan anlatım', ['Basit, doğrusal ve kronolojik bir anlatım düzeni', 'Tek bir anlatıcı', 'Yalnızca diyaloglarla yazılmış olma'], 'Boom romanları, yapı, zaman ve dil oyunlarıyla klasik romanın sınırlarını zorladı.'),
  ('Hawthorne\'un \'Genç Goodman Brown\' öyküsünde kahramanın ormandaki gece deneyimi neyi sorgular?', 'Saygın görünenlerin günahkârlığı inancını ve imanın dayanıklılığını', ['Ormanda gömülü bir hazinenin yerinin şifreli bir harita yardımıyla bulunması', 'Bir kralın sağlığını', 'Bir köyün yangınını'], 'Brown, ormanda köy halkının şeytanla ayine katıldığını görür; sabah dünyaya ve eşine güvenini yitirir.'),
  ('Faulkner\'ın \'Kutsal Yer\' (Sanctuary) romanı hangi nedenle tartışmalıdır?', 'Şiddet ve cinsel saldırı gibi karanlık temaları işlemesi', ['Hükümetin politikasını açıkça desteklemesi ve propaganda yapması', 'Dini yüceltmesi', 'Çocuk eğitimini anlatması'], 'Roman, Temple Drake\'in kaçırılması ve Güney\'in ahlaki çürümesi üzerinden sarsıcı bir şiddet anlatısı sunar.'),
  ('Steinbeck\'in \'Tatlı Perşembe\' romanında Doc ve Mack\'in çevresi hangi dünyayı anlatır?', 'Monterey\'de balık fabrikası mahallesindeki yoksul ama cana yakın insanları', ['Hollywood\'u', 'New York borsasını', 'Texas\'taki petrol sahalarını'], 'Roman, yoksullar arasındaki dayanışma, mizah ve insani sıcaklığı Cannery Row mahallesi üzerinden anlatır.'),
  ('Whitman\'ın \'Demokratik Manzaralar\' (Democratic Vistas) denemesi neyi tartışır?', 'İç Savaş sonrası Amerikan demokrasisinin geleceğini', ['Antik Yunan\'ın demokratik kurumlarını ve felsefesini', 'Avrupa monarşilerini', 'Bilimsel icatları'], 'Whitman, maddi ilerlemenin ruhsal ve edebi gelişme olmadan yetmeyeceğini savundu.'),
  ('Borges\'in \'Ölümsüz\' öyküsünde Homeros\'un kimliğiyle ilgili ortaya konan fikir nedir?', 'Ölümsüz kişinin Homeros olduğunu ve kimliğini yitirdiğini', ['Homeros\'un hiç var olmadığını ve destanların kolektif yazıldığını', 'Homeros\'un kör olmadığı', 'Homeros\'un asker olduğu'], 'Öykü, ölümsüzlüğün anlamsızlığını ve zamanla kimliklerin eridiğini anlatır.'),
  ('Borges\'in \'Güney\' öyküsünde Dahlmann\'ın sonunda yaptığı şey neyi simgeler?', 'Gerçek ya da hayal bir düelloyla onurlu ölümü seçmeyi', ['Şehre dönüp avukatlık mesleğine yeniden başlayıp barışmayı', 'Hastaneden kaçmayı', 'Bir kitabı yayımlatmayı'], 'Dahlmann, hastalıktan ölmek yerine bıçaklı kavgaya girer; öykü gerçek ve hayal arasındaki sınırı bulanıklaştırır.'),
  ('Cortázar\'ın \'Güneyin Otobanı\' öyküsünde trafik sıkışıklığı neyi simgeler?', 'Modern insanın yarattığı kapana kısılmışlığı ve dayanışmanın doğuşunu', ['Savaşın kaçınılmazlığını ve ordunun şehirleri kuşatmasının yarattığı paniği', 'Doğal afeti', 'Siyasi darbeyi'], 'Günlerce süren trafikte insanlar birbirine yakınlaşır; fakat sıkışıklık çözüldüğünde yeniden birbirlerinden kopar.'),
  ('Latin Amerika\'da \'Post-Boom\' kuşağının Boom\'dan farkı nedir?', 'Daha sade anlatım, gündelik yaşam ve kadın seslerini', ['Daha deneysel, karmaşık ve elit bir anlatım biçimini', 'Yalnızca şiir üretimi', 'Tiyatro ağırlığı'], 'Boom\'un karmaşık ve elit üslubuna tepki olarak Allende, Skármeta gibi yazarlar daha okunur anlatı biçimleri kurdu.'),
  ('Pablo Neruda ile Federico García Lorca\'nın dostluğu hangi gerçeği ortaya koyar?', 'İspanyol ve Latin Amerikalı şairlerin birbirini etkilemesi', ['İkisinin de aynı kasabada doğup aynı okulda birlikte büyüdüğünü', 'İkisinin de romancı olduğunu', 'İkisinin de Nobel aldığını'], 'Neruda, Lorca\'yla Buenos Aires ve Madrid\'de tanıştı; Lorca\'nın öldürülmesi Neruda\'yı etkiledi ve onu siyasal şiire yöneltti.'),
  ('Hans Fallada\'nın \'Herkes Kendi İçin Ölür\' romanı hangi gerçek olaydan esinlenmiştir?', 'Nazi rejimine karşı kartpostallarla direnen bir Berlinli çiftin öyküsünden', ['Bir savaş esiri kaçışından', 'Bir kıtlık döneminden', 'Bir isyan hareketinden'], 'Otto ve Elise Hampel, Hitler karşıtı mesajlar yazdıkları için idam edildi; Fallada onların hikâyesini romanlaştırdı.'),
  ('Anna Seghers\'in \'Yedinci Haç\' romanı neyi anlatır?', 'Kamptan kaçan yedi mahkûmdan birinin saklanma serüvenini', ['Okyanus aşan bir gemi yolculuğunu ve mürettebatın isyanını', 'Bir savaş zaferini', 'Bir aşk üçgenini'], 'Roman, Nazi Almanyası\'nda direniş ve dayanışmanın yer aldığı bir kaçış anlatısıdır.'),
  ('Bertolt Brecht\'in sürgün yıllarında yazdığı \'Sonradan Doğanlara\' şiirinde şair neyi sorgular?', 'Kötü zamanlarda ağaçlar hakkında konuşmanın suç olup olmadığını', ['Gelecek kuşakların zenginliğini', 'Doğanın güzelliğini', 'Savaşın kazananını'], 'Brecht, sessizlik ve zulüm çağında sanatın ve sıradan konuşmaların ahlaki sorumluluğunu sorgular.'),
  ('Octavio Paz\'ın şiirini Doğu felsefesi ve Sürrealizm ile birlikte düşünmek neden uygundur?', 'Hindistan büyükelçiliği ve Paris\'te Breton\'la tanışması şiirini biçimlendirmiştir', ['Hiç yurtdışında yaşamamış, tüm yaşamını Meksika kırsalında sıradan bir köylü olarak geçirmiştir', 'Yalnızca Roma\'da çalışmıştır', 'Sadece klasik şiir yazmıştır'], 'Paz, Hint düşüncesi ve Sürrealizmi kendi şiirinde birleştirdi; \'Güneş Taşı\' ve \'Kuzgun Bahçesi\' bunun örnekleridir.'),
  ('Salinger\'in \'Muz Balığı İçin Mükemmel Bir Gün\' öyküsü hangi çarpıcı olayla biter?', 'Seymour Glass\'ın otel odasında kendini vurması', ['Muz balığı avında yaşanan bir kaza', 'Sibyl\'in denizde kaybolması', 'Seymour\'un karısıyla barışması'], 'Öykü hafif ve oyuncul bir plaj sahnesiyle ilerlerken sürpriz bir intiharla biter; Salinger\'in Dokuz Öykü kitabında yer alır.'),
  ('Nezahualcóyotl\'ın edebiyat tarihindeki yeri nedir?', 'Aztek dünyasında hem hükümdar hem şair olarak anılması', ['İspanyol fatihlerin ilk tarihçisi olması', 'Maya takviminin yaratıcısı olması', 'İnka destanlarının derleyicisi olması'], 'Texcoco hükümdarı Nezahualcóyotl, Nahuatl dilindeki şiirleriyle yerli Amerika\'nın en bilinen şairlerindendir.'),
  ('Jorge Icaza\'nın \'Huasipungo\' romanı hangi ülkenin yerlici edebiyatının örneğidir?', 'Ekvador', ['Arjantin', 'Küba', 'Uruguay'], 'Icaza, And dağlarındaki yerli köylülerin toprak sahipleri tarafından sömürülüşünü çarpıcı bir gerçekçilikle anlatır.'),
  ('Machado de Assis\'in Brezilya edebiyatındaki kurumsal rolü nedir?', 'Brezilya Edebiyat Akademisi\'nin ilk başkanı olması', ['İlk Brezilya cumhurbaşkanı olması', 'İlk Brezilya anayasasını yazması', 'Brezilya\'da ilk tiyatroyu kurması'], 'Machado de Assis, 1897\'de kurulan Brezilya Edebiyat Akademisi\'nin ilk başkanıydı; romanları modern Brezilya edebiyatının temelidir.'),
  ('Ernst Jünger\'in \'Çelik Fırtınalar\' kitabı hangi türdedir ve neyi anlatır?', 'Birinci Dünya Savaşı siperlerindeki deneyimlerini aktaran savaş günlüğü', ['Orta Çağ şövalyeliğini işleyen tarihî roman', 'Napolyon seferlerini anlatan destan', 'Soğuk Savaş casuslarını anlatan polisiye'], 'Jünger\'in anıları, savaşı estetik ve soğukkanlı bir gözle anlatması nedeniyle Remarque\'ın tutumundan farklı biçimde tartışılmıştır.'),
  ('Schnitzler\'in \'Dönence\' (Reigen) oyununun yapısı nasıldır?', 'Her sahnede bir önceki sahnenin kişisinin yeni biriyle buluştuğu on diyalogluk bir zincir', ['Tek bir kahramanın on yıllık günlüğü', 'Yedi perdelik klasik trajedi', 'Karşılıklı mektuplardan oluşan bir roman'], 'Oyun, toplumsal sınıfları aşan on cinsel buluşmayı bir halka gibi birbirine bağlar; yayımlandığında skandal yarattı.'),
  ('Fontane\'nin \'Mark Brandenburg\'da Yürüyüşler\' kitabı hangi türün örneğidir?', 'Bölge gezi ve tarih yazısı', ['Epik şiir', 'Şövalye romanı', 'Tiyatro eleştirisi'], 'Fontane, Brandenburg bölgesinin köylerini, malikânelerini ve tarihini gezi notları biçiminde anlatarak sonraki romanlarına malzeme topladı.'),
  ('Latin Amerika \'diktatör romanı\' türü ile George Orwell\'ın \'1984\'ünde işlenen otoriter rejim temasının ortak noktası nedir?', 'İktidarın dil, korku ve gözetim yoluyla bireyi baskı altına alması', ['Savaşın zaferle sonuçlanması', 'Doğanın yok oluşu', 'Ekonomik kalkınmanın başarısı'], 'Her iki gelenek de otoriter rejimin toplumsal belleği ve dili denetleme biçimlerini edebî bir yapıyla eleştirir.'),
];
